import{E as e,F as t,q as n,w as r}from"./vue.runtime.esm-bundler-DZZTqpJU.js";t();var i={class:`markdown-body`},a={__name:`xpath.zh`,setup(t,{expose:a}){return a({frontmatter:{}}),(t,a)=>(n(),r(`div`,i,[...a[0]||=[e(`<blockquote><p>致谢原作者: <a href="https://gist.github.com/jmaccabee/550a0b9fcfdc7e6b170cd34c6ec7bc56">https://gist.github.com/jmaccabee/550a0b9fcfdc7e6b170cd34c6ec7bc56</a></p></blockquote><h2>0. XPath 示例</h2><blockquote><p>更多内容: <a href="http://xpath.alephzarro.com/content/cheatsheet.html">http://xpath.alephzarro.com/content/cheatsheet.html</a></p></blockquote><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>//hr[@class=&quot;edge&quot; and position()=1]</code></td><td>每个 ‘edge’ 类的第一个 hr</td></tr><tr><td><code>//table[count(tr)=1 and count(tr/td)=2]</code></td><td>所有 1 行 2 列的表格</td></tr><tr><td><code>//div/form/parent::*</code></td><td>所有包含 form 的 div</td></tr><tr><td><code>./div/b</code></td><td>相对路径</td></tr><tr><td><code>//table[parent::div[@class=&quot;pad&quot;] and not(@id)]//a</code></td><td>无 id 且位于 “pad” 类 div 中的表格里的任意锚链接</td></tr><tr><td><code>/html/body/div/*[preceding-sibling::h4]</code></td><td>h4 之后的所有内容</td></tr><tr><td><code>//tr/td[font[@class=&quot;head&quot; and text()=&quot;TRACK&quot;]]</code></td><td>所有包含 “head” 类且文本为 “TRACK” 的 font 的 td</td></tr><tr><td><code>./table/tr[last()]</code></td><td>表格的最后一行</td></tr><tr><td><code>//rdf:Seq/rdf:li/em:id</code></td><td>使用命名空间</td></tr><tr><td><code>//a/@href</code></td><td>所有锚链接的 href</td></tr><tr><td><code>//*[count(*)=3]</code></td><td>所有拥有 3 个子节点的节点</td></tr><tr><td><code>//var|//acronym</code></td><td>所有的 var 和 acronym</td></tr></tbody></table><h2>1. 通用</h2><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>/html</code></td><td>整个网页（CSS: html）</td></tr><tr><td><code>/html/body</code></td><td>整个网页主体（CSS: body）</td></tr><tr><td><code>//text()</code></td><td>网页中的所有文本节点</td></tr><tr><td><code>/html/body/.../.../.../E</code></td><td>通过绝对路径引用的元素 &lt;E&gt;（CSS: body &gt; … &gt; … &gt; … &gt; E）</td></tr></tbody></table><h2>2. 标签</h2><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>//E</code></td><td>通过相对路径引用的元素 &lt;E&gt;（CSS: E）</td></tr><tr><td><code>(//E)[2]</code></td><td>页面中第二个 &lt;E&gt; 元素</td></tr><tr><td><code>//img</code></td><td>图片元素（CSS: img）</td></tr><tr><td><code>//E[@A]</code></td><td>具有属性 A 的元素 &lt;E&gt;（CSS: E[A]）</td></tr><tr><td><code>//E[@A=&quot;t&quot;]</code></td><td>属性 A 精确包含文本 ‘t’ 的元素 &lt;E&gt;（CSS: E[A=‘t’]）</td></tr><tr><td><code>//E[contains(@A,&quot;t&quot;)]</code></td><td>属性 A 包含文本 ‘t’ 的元素 &lt;E&gt;（CSS: E[A*=‘t’]）</td></tr><tr><td><code>//E[starts-with(@A, &quot;t&quot;)]</code></td><td>属性 A 以 ‘t’ 开头的元素 &lt;E&gt;（CSS: E[A^=‘t’]）</td></tr><tr><td><code>//E[ends-with(@A, &quot;t&quot;)]</code></td><td>属性 A 以 ‘t’ 结尾的元素 &lt;E&gt;（CSS: E[A$=‘t’]）</td></tr><tr><td><code>//E[contains(concat(&quot; &quot;, @A, &quot; &quot;), &quot; w &quot;)</code></td><td>属性 A 包含单词 ‘w’ 的元素 &lt;E&gt;（CSS: E[A~=‘w’]）</td></tr><tr><td><code>//E[matches(@A, &quot;r&quot;)]</code></td><td>属性 A 匹配正则表达式 ‘r’ 的元素 &lt;E&gt;</td></tr><tr><td><code>//E1[@id=I1] | //E2[@id=I2]</code></td><td>id 为 I1 的元素 &lt;E1&gt; 或 id 为 I2 的元素 &lt;E2&gt;（CSS: E1#I1, E2#I2）</td></tr><tr><td><code>//E1[@id=I1 or @id=I2]</code></td><td>id 为 I1 或 I2 的元素 &lt;E1&gt;（CSS: E1#I1, E1#I2）</td></tr></tbody></table><h2>3. 属性</h2><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>//E/@A</code></td><td>元素 &lt;E&gt; 的属性 A（CSS: E@A）</td></tr><tr><td><code>//*/@A</code></td><td>任意元素的属性 A（CSS: *@A）</td></tr><tr><td><code>//E[@A2=&quot;t&quot;]/@A1</code></td><td>属性 A2 精确为 ‘t’ 的元素 &lt;E&gt; 的属性 A1（CSS: E[A2=‘t’]@A1）</td></tr><tr><td><code>//E[contains(@A,&quot;t&quot;)]/@A</code></td><td>属性 A 包含 ‘t’ 的元素 &lt;E&gt; 的属性 A（CSS: E[A*=‘t’]@A）</td></tr></tbody></table><h2>4. ID 和 Name</h2><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>//*[@id=&quot;I&quot;]</code></td><td>id 为 I 的元素（CSS: #I）</td></tr><tr><td><code>//E[@id=&quot;I&quot;]</code></td><td>id 为 I 的元素 &lt;E&gt;（CSS: E#I）</td></tr><tr><td><code>//*[@name=&quot;N&quot;]</code></td><td>具有指定 name 的元素（CSS: [name=‘N’]）</td></tr><tr><td><code>//E[@name=&quot;N&quot;]</code></td><td>具有指定 name 的元素 &lt;E&gt;（CSS: E[name=‘N’]）</td></tr><tr><td><code>//*[@id=&quot;X&quot; or @name=&quot;X&quot;]</code></td><td>id 为 X 或 name 为 X 的元素</td></tr><tr><td><code>//*[@name=&quot;N&quot;][v+1]</code></td><td>name 为 N 且指定从 0 开始的索引 ‘v’ 的元素（CSS: [name=‘N’]:nth-child(v+1)）</td></tr><tr><td><code>//*[@name=&quot;N&quot;][@value=&quot;v&quot;]</code></td><td>name 为 N 且值为 ‘v’ 的元素（CSS: *[name=‘N’][value=‘v’]）</td></tr></tbody></table><h2>5. 语言和类</h2><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>//E[@lang=&quot;L&quot; or starts-with(@lang, concat(&quot;L&quot;, &quot;-&quot;))]</code></td><td>显式使用语言 L 或其子代码的元素 &lt;E&gt;（CSS: E[lang|=L]）</td></tr><tr><td><code>//*[contains(concat(&quot; &quot;, @class, &quot; &quot;), &quot; C &quot;)]</code></td><td>拥有类 C 的元素（CSS: .C）</td></tr><tr><td><code>//E[contains(concat(&quot; &quot;, @class, &quot; &quot;), &quot; C &quot;)]</code></td><td>拥有类 C 的元素 &lt;E&gt;（CSS: E.C）</td></tr></tbody></table><h2>6. 文本和链接</h2><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>//*[.=&quot;t&quot;]</code></td><td>精确包含文本 ‘t’ 的元素</td></tr><tr><td><code>//E[contains(text(), &quot;t&quot;)]</code></td><td>包含文本 ‘t’ 的元素 &lt;E&gt;（CSS: E:contains(‘t’)）</td></tr><tr><td><code>//a</code></td><td>链接元素（CSS: a）</td></tr><tr><td><code>//a[.=&quot;t&quot;]</code></td><td>精确包含文本 ‘t’ 的元素 &lt;a&gt;</td></tr><tr><td><code>//a[contains(text(), &quot;t&quot;)]</code></td><td>包含文本 ‘t’ 的元素 &lt;a&gt;（CSS: a:contains(‘t’)）</td></tr><tr><td><code>//a[@href=&quot;url&quot;]</code></td><td>目标链接为 ‘url’ 的 &lt;a&gt;（CSS: a[href=‘url’]）</td></tr><tr><td><code>//a[.=&quot;t&quot;]/@href</code></td><td>文本精确为 ‘t’ 的链接 URL</td></tr></tbody></table><h2>7. 父级和子级</h2><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>//E/*[1]</code></td><td>元素 &lt;E&gt; 的第一个子元素（CSS: E &gt; *:first-child）</td></tr><tr><td><code>//E[1]</code></td><td>第一个 &lt;E&gt; 子元素（CSS: E:first-of-type）</td></tr><tr><td><code>//E/*[last()]</code></td><td>元素 E 的最后一个子元素（CSS: E *:last-child）</td></tr><tr><td><code>//E[last()]</code></td><td>最后一个 &lt;E&gt; 子元素（CSS: E:last-of-type）</td></tr><tr><td><code>//E[2]</code></td><td>第二个 &lt;E&gt; 子元素（CSS: E:nth-of-type(2)）</td></tr><tr><td><code>//*[2][name()=&quot;E&quot;]</code></td><td>是 &lt;E&gt; 元素的第二个子元素（CSS: E:nth-child(2)）</td></tr><tr><td><code>//E[last()-1]</code></td><td>倒数第二个 &lt;E&gt; 子元素（CSS: E:nth-last-of-type(2)）</td></tr><tr><td><code>//*[last()-1][name()=&quot;E&quot;]</code></td><td>倒数第二个是 &lt;E&gt; 元素的子元素（CSS: E:nth-last-child(2)）</td></tr><tr><td><code>//E1/[E2 and not( *[not(self::E2)])]</code></td><td>仅含 &lt;E2&gt; 子元素的 &lt;E1&gt; 元素</td></tr><tr><td><code>//E/..</code></td><td>元素 &lt;E&gt; 的父元素</td></tr><tr><td><code>//*[@id=&quot;I&quot;]/.../.../.../E</code></td><td>使用指定路径的 id 为 I 的元素的后代 &lt;E&gt;（CSS: #I &gt; … &gt; … &gt; … &gt; E）</td></tr><tr><td><code>//*[@id=&quot;I&quot;]//E</code></td><td>使用未指定路径的 id 为 I 的元素的后代 &lt;E&gt;（CSS: #I E）</td></tr><tr><td><code>//E[count(*)=0]</code></td><td>无子元素的元素 &lt;E&gt;（E:empty）</td></tr><tr><td><code>//E[count(*)=1]</code></td><td>只有一个子元素的元素 &lt;E&gt;</td></tr><tr><td><code>//E[count(preceding-sibling::*)+count(following-sibling::*)=0]</code></td><td>作为唯一子元素的元素 &lt;E&gt;（CSS: E:only-child）</td></tr><tr><td><code>//E[count(../E) = 1]</code></td><td>无 &lt;E&gt; 兄弟元素的元素 &lt;E&gt;（CSS: E:only-of-type）</td></tr><tr><td><code>//E[position() mod N = M + 1]</code></td><td>从第 (M+1) 个开始的每第 N 个元素（CSS: E:nth-child(Nn+M)）</td></tr></tbody></table><h2>8. 兄弟节点</h2><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>//E2/following-sibling::E1</code></td><td>跟在某个兄弟节点 &lt;E2&gt; 之后的元素 &lt;E1&gt;（CSS: E2 ~ E1）</td></tr><tr><td><code>//E2/following-sibling::*[1][name()=&quot;E1&quot;]</code></td><td>紧跟在兄弟节点 &lt;E2&gt; 之后的元素 &lt;E1&gt;（CSS: E2 + E1）</td></tr><tr><td><code>//E2/following-sibling::*[2][name()=&quot;E1&quot;]</code></td><td>跟在兄弟节点 &lt;E2&gt; 之后且中间间隔一个元素的元素 &lt;E1&gt;（CSS: E2 + * + E1）</td></tr><tr><td><code>//E/following-sibling::*</code></td><td>紧跟在 &lt;E&gt; 之后的兄弟元素（CSS: E + *）</td></tr><tr><td><code>//E2/preceding-sibling::E1</code></td><td>在某个兄弟节点 &lt;E2&gt; 之前的元素 &lt;E1&gt;</td></tr><tr><td><code>//E2/preceding-sibling::*[1][name()=&quot;E1&quot;]</code></td><td>紧邻兄弟节点 &lt;E2&gt; 之前的元素 &lt;E1&gt;</td></tr><tr><td><code>//E2/preceding-sibling::*[2][name()=&quot;E1&quot;]</code></td><td>在兄弟节点 &lt;E2&gt; 之前且中间间隔一个元素的元素 &lt;E1&gt;</td></tr><tr><td><code>//E/preceding-sibling::*[1]</code></td><td>紧邻 &lt;E&gt; 之前的兄弟元素</td></tr></tbody></table><h2>9. 表格单元格</h2><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>//*[@id=&quot;TestTable&quot;]//tr[3]//td[2]</code></td><td>按行和列定位的单元格（如第 3 行第 2 列）（CSS: #TestTable tr:nth-child(3) td:nth-child(2)）</td></tr><tr><td><code>//td[preceding-sibling::td=&quot;t&quot;]</code></td><td>紧跟在精确包含 ‘t’ 的单元格之后的单元格</td></tr><tr><td><code>td[preceding-sibling::td[contains(.,&quot;t&quot;)]]</code></td><td>紧跟在包含 ‘t’ 的单元格之后的单元格（CSS: td:contains(‘t’) ~ td）</td></tr></tbody></table><h2>10. 动态</h2><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>//E[@disabled]</code></td><td>被禁用的用户界面元素 &lt;E&gt;（CSS: E:disabled）</td></tr><tr><td><code>//*[not(@disabled)]</code></td><td>被启用的用户界面元素（CSS: E:enabled）</td></tr><tr><td><code>//*[@checked]</code></td><td>被选中的复选框（或单选按钮）（CSS: *:checked）</td></tr></tbody></table><h2>11. XPath 函数</h2><blockquote><p><a href="https://developer.mozilla.org/en-US/docs/Web/XPath/Functions">https://developer.mozilla.org/en-US/docs/Web/XPath/Functions</a></p></blockquote><h3>11.1. 转换</h3><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>boolean(expression)</code></td><td>对表达式求值并返回 true 或 false。</td></tr><tr><td><code>string([object])</code></td><td>将给定参数转换为字符串。</td></tr><tr><td><code>number([object])</code></td><td>将对象转换为数字并返回该数字。</td></tr></tbody></table><h3>11.2. 数学</h3><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>ceiling(number)</code></td><td>对小数求值并返回大于或等于该小数的最小整数。</td></tr><tr><td><code>floor(number)</code></td><td>对小数求值并返回小于或等于该小数的最大整数。</td></tr><tr><td><code>round(decimal)</code></td><td>返回最接近给定数字的整数。</td></tr><tr><td><code>sum(node-set)</code></td><td>返回给定节点集中各节点数值的总和。</td></tr></tbody></table><h3>11.3. 逻辑</h3><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>true()</code></td><td>返回布尔值 true。</td></tr><tr><td><code>false()</code></td><td>返回布尔值 false。</td></tr><tr><td><code>not(expression)</code></td><td>对布尔表达式求值并返回相反的值。</td></tr></tbody></table><h3>11.4. 节点</h3><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>lang(string)</code></td><td>判断上下文节点是否匹配给定语言，返回布尔值 true 或 false。</td></tr><tr><td><code>name([node-set])</code></td><td>返回表示给定节点集中第一个节点的 QName 的字符串。</td></tr><tr><td><code>namespace-uri([node-set])</code></td><td>返回表示给定节点集中第一个节点的命名空间 URI 的字符串。</td></tr></tbody></table><h3>11.5. 上下文</h3><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>count(node-set)</code></td><td>统计节点集中的节点数量并返回一个整数。</td></tr><tr><td><code>function-available(name)</code></td><td>判断给定函数是否可用，返回布尔值 true 或 false。</td></tr><tr><td><code>last()</code></td><td>返回等于表达式求值上下文上下文大小的数字。</td></tr><tr><td><code>position()</code></td><td>返回等于表达式求值上下文上下文位置的数字。</td></tr></tbody></table><h3>11.6. 字符串</h3><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>contains(haystack-string, needle-string)</code></td><td>判断第一个参数字符串是否包含第二个参数字符串，返回布尔值 true 或 false。</td></tr><tr><td><code>concat(string1, string2 [stringn]*)</code></td><td>拼接两个或多个字符串并返回结果字符串。</td></tr><tr><td><code>normalize-space(string)</code></td><td>去除字符串首尾空白字符，将空白字符序列替换为单个空格，并返回结果字符串。</td></tr><tr><td><code>starts-with(haystack, needle)</code></td><td>检查第一个字符串是否以第二个字符串开头，返回 true 或 false。</td></tr><tr><td><code>string-length([string])</code></td><td>返回等于给定字符串中字符数的数字。</td></tr><tr><td><code>substring(string, start [length])</code></td><td>返回给定字符串的一部分。</td></tr><tr><td><code>substring-after(haystack, needle)</code></td><td>返回给定字符串中指定子字符串之后剩余的字符串。</td></tr><tr><td><code>substring-before(haystack, needle)</code></td><td>返回给定字符串中指定子字符串之前剩余的字符串。</td></tr><tr><td><code>translate(string, abc, XYZ)</code></td><td>对字符串和一组待转换字符进行求值，返回转换后的字符串。</td></tr></tbody></table><h2>12. XPath 轴</h2><table><thead><tr><th>XPath</th><th>描述</th></tr></thead><tbody><tr><td><code>ancestor</code></td><td>表示上下文节点的所有祖先，从父节点开始一直到根节点。</td></tr><tr><td><code>ancestor-or-self</code></td><td>表示上下文节点及其所有祖先，包括根节点。</td></tr><tr><td><code>attribute (@)</code></td><td>表示上下文节点的属性。只有元素才有属性。此轴可用 @ 符号缩写。</td></tr><tr><td><code>child (/)</code></td><td>表示上下文节点的子节点。如果 XPath 表达式未指定轴，则默认使用此轴。由于只有根节点或元素节点有子节点，其他用法不会选中任何内容。</td></tr><tr><td><code>descendant (//)</code></td><td>表示上下文节点的所有子节点，以及子节点的子节点，依此类推。不包括属性和命名空间节点——属性节点的父节点是元素节点，但属性节点不是其父节点的子节点。</td></tr><tr><td><code>descendant-or-self</code></td><td>表示上下文节点及其所有后代。不包括属性和命名空间节点——属性节点的父节点是元素节点，但属性节点不是其父节点的子节点。</td></tr><tr><td><code>following</code></td><td>表示上下文节点之后出现的所有节点，不包括后代、属性和命名空间节点。</td></tr><tr><td><code>following-sibling</code></td><td>表示与上下文节点具有相同父节点且在源文档中位于上下文节点之后的所有节点。</td></tr><tr><td><code>parent(..)</code></td><td>表示作为上下文节点父节点的单个节点。可用两个点 (…) 缩写。</td></tr><tr><td><code>preceding</code></td><td>表示文档中位于上下文节点之前的所有节点，不包括祖先、属性和命名空间节点。</td></tr><tr><td><code>preceding-sibling</code></td><td>表示与上下文节点具有相同父节点且在源文档中位于上下文节点之前的所有节点。</td></tr><tr><td><code>self (.)</code></td><td>表示上下文节点本身。可用单个点 (.) 缩写。</td></tr></tbody></table>`,40)]]))}};export{a as default};